require "rails_helper"

RSpec.describe Timekeeping::ReservationDerivation do
  it "refuses a recorded invoice number that only another company has and reserves nothing for it" do
    row = {
      "id" => 1, "company_id" => 1, "version" => 0, "project_id" => 5, "user_id" => 3, "agent_id" => nil,
      "work_date" => Date.new(2026, 10, 1), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => Time.utc(2026, 10, 1), "updated_at" => Time.utc(2026, 10, 1)
    }

    # Company 1 owns invoice 10, numbered "FL-1". The record files the link under
    # "CK-9", a number that exists only in another company, so it must not resolve.
    # Issue: "Refuse, never guess, when a number is missing, matches no invoice of
    # that company, or would link an entry to another company's invoice."
    result = described_class.derive(
      company_id: 1,
      entries: [{ id: 1, locked: false, company_id: 1, join_company_id: 1, row: }],
      links: [{ entry_id: 1, invoice_id: 10, invoice_company_id: 1, draft: false, discarded: false }],
      invoice_numbers: { 10 => "FL-1" },
      recorded_invoices: { "CK-9" => { "entry_ids" => [1], "disposition" => "reserve" } },
      generation: 7,
      captured_at: Time.utc(2026, 10, 25, 12)
    )

    expect(result[:refusals]).not_to be_empty
    expect(result[:reservations]).to be_empty
    expect(result[:corrections]).to be_empty
  end
end

