require "rails_helper"

RSpec.describe Timekeeping::ReservationDerivation do
  it "refuses an entry whose stored company_id is nil or differs from its project client company join" do
    base_row = {
      "version" => 0, "project_id" => 5, "user_id" => 3, "agent_id" => nil,
      "work_date" => Date.new(2026, 10, 1), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => true, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => Time.utc(2026, 10, 1), "updated_at" => Time.utc(2026, 10, 1)
    }

    # Issue: "An entry whose `company_id` differs from its project → client → company
    # join is also refused for that company."
    [nil, 2].each do |stored_company_id|
      result = described_class.derive(
        company_id: 1,
        entries: [{ id: 3, locked: true, company_id: stored_company_id, join_company_id: 1,
                    row: base_row.merge("id" => 3, "company_id" => stored_company_id) }],
        links: [{ entry_id: 3, invoice_id: 30, invoice_company_id: 1, draft: false, discarded: false }],
        invoice_numbers: { 30 => "FL-3" },
        recorded_invoices: {},
        generation: 7,
        captured_at: Time.utc(2026, 10, 25, 12)
      )

      expect(result[:refusals]).not_to be_empty, "stored company_id #{stored_company_id.inspect} was not refused"
      expect(result[:reservations]).to be_empty
    end
  end
end

require "rails_helper"

RSpec.describe Timekeeping::ReservationDerivation do
  it "does not release a re-locked entry that also has a kept invoice and gives it exactly one reservation" do
    row = {
      "id" => 4, "company_id" => 1, "version" => 0, "project_id" => 5, "user_id" => 3, "agent_id" => nil,
      "work_date" => Date.new(2026, 10, 1), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => true, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => Time.utc(2026, 10, 1), "updated_at" => Time.utc(2026, 10, 1)
    }

    # Issue: "An entry locked only by the old draft-discard re-lock (L2) is released,
    # as a listed correction, only when no other committed or pending owner exists."
    result = described_class.derive(
      company_id: 1,
      entries: [{ id: 4, locked: true, company_id: 1, join_company_id: 1, row: }],
      links: [
        { entry_id: 4, invoice_id: 41, invoice_company_id: 1, draft: true, discarded: true },
        { entry_id: 4, invoice_id: 40, invoice_company_id: 1, draft: false, discarded: false }
      ],
      invoice_numbers: { 40 => "FL-40", 41 => "FL-41" },
      recorded_invoices: {},
      generation: 7,
      captured_at: Time.utc(2026, 10, 25, 12)
    )

    expect(result[:refusals]).to be_empty
    expect(result[:corrections]).to be_empty
    expect(result[:reservations].size).to eq(1)
    expect(result[:reservations].first).to include(
      "company_id" => 1, "entry_id" => 4, "invoice_id" => 40, "state" => "committed", "disposition" => "active"
    )
  end
end

require "rails_helper"

RSpec.describe Timekeeping::ReservationDerivation do
  it "derives the same rows on a retry and never the same operation_id for two companies" do
    derive_for = lambda do |company_id|
      row = {
        "id" => 5, "company_id" => company_id, "version" => 0, "project_id" => 5, "user_id" => 3, "agent_id" => nil,
        "work_date" => Date.new(2026, 10, 1), "duration" => 60.0, "note" => "", "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => true, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => Time.utc(2026, 10, 1), "updated_at" => Time.utc(2026, 10, 1)
      }
      described_class.derive(
        company_id:,
        entries: [{ id: 5, locked: true, company_id:, join_company_id: company_id, row: }],
        links: [{ entry_id: 5, invoice_id: 50, invoice_company_id: company_id, draft: false, discarded: false }],
        invoice_numbers: { 50 => "INV-50" },
        recorded_invoices: {},
        generation: 7,
        captured_at: Time.utc(2026, 10, 25, 12)
      )
    end

    # Issue: "Make every derived value repeatable: a reservation's `operation_id` is a
    # UUIDv5 of company, entry and invoice, and timestamps are a capture time passed in."
    first = derive_for.call(1)
    retry_run = derive_for.call(1)
    other_company = derive_for.call(2)

    expect(retry_run).to eq(first)
    expect(first[:reservations].first["created_at"]).to eq(Time.utc(2026, 10, 25, 12))
    expect(first[:reservations].first["operation_id"]).not_to eq(other_company[:reservations].first["operation_id"])
  end
end
